            "error": "field 'signature' must be 128 lowercase hex characters"
        }

    mode = SYNC_MODE_ATTESTED
    with self.store.lock:
        self._prune_expired_syncs()
        key = (source, request_id)
        existing = self.store.attested_syncs.get(key)

        if existing is None:
